import{z as i,x as l,o as t,c as d,q as o,j as r,D as e,d as s,s as n,S as p}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"CRSP / Compustat 对齐","description":"","frontmatter":{"title":"CRSP / Compustat 对齐","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/crsp-compustat.md","filePath":"quant/crsp-compustat.md","lastUpdated":1791413859000}'),C={name:"quant/crsp-compustat.md"};function A(m,a,c,B,u,h){const E=l("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="crsp-compustat-对齐" tabindex="-1">CRSP / Compustat 对齐 <a class="header-anchor" href="#crsp-compustat-对齐" aria-label="Permalink to &quot;CRSP / Compustat 对齐&quot;">​</a></h1><div class="epigraph"><p>价格在 CRSP，报表在 Compustat；两者的主键不是同一家公司的同一天。链接错了，因子就是在把别人的盈利接到自己的收益上。</p><footer>—— WRDS CRSP/Compustat Merged（CCM）说明；Shumway, The Delisting Bias in CRSP Data, Journal of Finance, 1997；对照 Bali, Engle and Murray 对美股实证数据实践的讨论</footer></div><p><a href="/quant/options-expiration-process">上一课</a>收束交易所课序。本单元转到研究基础设施。缺口从「成交如何发生」变成<strong>历史如何被拼成可回测的面板</strong>。CRSP 给美股收益、退市、分布；Compustat 给会计。CCM 的 <code>gvkey–permno</code> 链接有生效日与链接类型。Shumway（1997）证明退市收益处理足以改变小盘结论。后课 TAQ 把频率从日频升到逐笔；本课先把公司身份与退市做对。不要在这里重写<a href="/quant/lob-structure">限价簿</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>日频美股研究的最小对象是：某 <code>permno</code> 在日 \\(t\\) 的收益，与当时已知的会计特征。Compustat 用 <code>gvkey</code> 与财政年度、季度。一家公司多次上市、并购、股票类别（A/B）、以及链接在某日才生效，使「按名称合并」非法。CCM 提供链接表，但链接有 <code>linktype</code>、<code>linkprim</code>、生效区间。用期末最新链接回填全历史，会把并购后的 gvkey 接到并购前的价格上。问题是点-in-time 链接：在 \\(t\\) 日只使用当时有效的主键映射。</p><p>退市：CRSP 的 delisting return 在部分代码上缺失或为部分收益。Shumway 建议对绩效退市填入惩罚性收益（原文对缺失的绩效退市给出经验处理）。忽略退市的组合会把消失的公司当成「不再存在于样本」而不是「以很差的价格退出」，小盘、亏损、高波动因子被高估。这与存活偏差同方向。</p><h3 id="财政日历不是交易日历" tabindex="-1">财政日历不是交易日历 <a class="header-anchor" href="#财政日历不是交易日历" aria-label="Permalink to &quot;财政日历不是交易日历&quot;">​</a></h3><p>会计时点是财季末与发布日。用财季末的 Compustat 行去对财季末当天的 CRSP 收益，通常前视：市场尚未看见报表。正确对齐是发布日（或保守的假设发布滞后）之后。后课重述会再加版本；本课先把「哪一期报表」与「哪一天可知」分开。IBES、共识在再后一课，不要把初步盈利与 Compustat 定稿混成一列。</p><p><span class="marginnote">中国没有 CRSP。对应工作是：交易所代码、公司代码、退市与 ST 状态、财务发布日。原则同构：身份、生效区间、退市收益、可知时点。不要把 CCM 的 permno 概念硬套到 A 股六位代码上而不做历史复用检查。</span></p><p><span class="marginnote">术语翻译：<code>gvkey</code> 是 Compustat 给「公司」发的永久编号，<code>permno</code> 是 CRSP 给「一只证券」发的永久编号。一家发行 A、B 两类股票的公司只有一个 gvkey，却有两个 permno——像一个人（公司）有两张不同的银行卡（证券）。链接表做的事就是把这两套编号在每一段时期内对上。</span></p><p><span class="marginnote">数字实例：假设财季末日是 3 月 31 日，报表 5 月 2 日才发布。4 月 15 日做截面排序时，正确可用的最新一期是「上一财年第四季度」；若你按 <code>datadate = 3 月 31 日</code> 去取数，等于提前两周看到了还没发布的利润表——这就是前视的一个具体形态。保守做法是给发布日再加几天缓冲。</span></p>',11)),(t(),r(p,null,{default:e(()=>[n(E,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20T%5B%22%E4%BA%A4%E6%98%93%E6%97%A5%20t%22%5D%20--%3E%20Q%5B%22%E6%89%BE%20t%20%E4%B9%8B%E5%89%8D%E5%B7%B2%E5%8F%91%E5%B8%83%E7%9A%84%E6%9C%80%E6%96%B0%E8%B4%A2%E6%8A%A5%E6%9C%9F%22%5D%0A%20%20Q%20--%3E%20Check%7B%22datadate%20%E7%9A%84%E5%AD%A3%E6%9C%AB%20%E6%97%A9%E4%BA%8E%20%E5%8F%91%E5%B8%83%E6%97%A5%E4%B8%8D%E6%99%9A%E4%BA%8E%20t%20%3F%22%7D%0A%20%20Check%20--%20%22%E5%90%A6%22%20--%3E%20Older%5B%22%E5%9B%9E%E9%80%80%E5%88%B0%E6%9B%B4%E6%97%A9%E4%B8%80%E6%9C%9F%22%5D%0A%20%20Older%20--%3E%20Check%0A%20%20Check%20--%20%22%E6%98%AF%22%20--%3E%20Use%5B%22%E4%BD%BF%E7%94%A8%E8%AF%A5%E6%9C%9F%E4%BC%9A%E8%AE%A1%E5%AD%97%E6%AE%B5%22%5D%0A%20%20L%5B%22%E6%9F%A5%20CCM%EF%BC%9At%20%E5%9C%A8%E9%93%BE%E6%8E%A5%E7%94%9F%E6%95%88%E5%8C%BA%E9%97%B4%E5%86%85%EF%BC%9F%22%5D%20--%3E%20Use%0A%20%20Use%20--%3E%20Row%5B%22%E5%BE%97%E5%88%B0%20permno%20%C3%97%20t%20%E7%9A%84%E4%B8%80%E8%A1%8C%E7%89%B9%E5%BE%81%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=o('<h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>流水线：以 CRSP 日频为骨架 → 用 CCM 在每条收益上左连接当时有效 gvkey → 再连接 Compustat 中 <code>datadate</code> 对应、且 <code>rdq</code>（或你定义的可知日）\\(\\le t\\) 的最新一期。链接类型过滤：研究须声明使用哪些 <code>linktype</code>（如 LC、LU）以及是否仅 primary。多类股票：明确是用 permno 还是用公司级市值加权。退市：实现 Shumway 或后继文献的填补规则，并报告填补前后的因子差异。</p><p>质量控制：孤立 gvkey、短链接、一天内多个 permno 映射到同一 gvkey。并购日附近的收益与会计应人工抽查。市值、价格、成交量用 CRSP；账面用 Compustat，注意单位与货币。ADR、REIT、封闭式基金是否进入样本必须显式，不能靠「CRSP 股票文件里有」默认纳入。</p><h3 id="退市与停牌是收益的一部分" tabindex="-1">退市与停牌是收益的一部分 <a class="header-anchor" href="#退市与停牌是收益的一部分" aria-label="Permalink to &quot;退市与停牌是收益的一部分&quot;">​</a></h3><p>停牌期无收益不是零收益。退市日收益若缺失，应按规则填或把该仓位标为不可交易退出。把退市公司直接从面板删除，等于条件于存活。这与指数成分课的存活偏差是同一类错误，后课会在指数层面再写一次。</p><p><span class="marginnote">常见误区：初学者容易以为「退市 = 数据库里少了一行，删掉就行」。实际上退市是持仓以某个（往往很差的）价格强制结算的一次真实收益。直觉类比：这就像统计餐馆存活率时只采访还开门的店——倒闭那批的亏损被整桌抹掉，平均成绩自然虚高。小盘因子组合每年有百分之几的成分退市，长期累积足以把结论从真变假。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>错误链接制造虚假的会计–收益关系：把成长公司的盈利接到价值公司的价格上，因子 IC 可以很好看，经济是错的。退市偏差选择性地丢掉左尾，使任何与困境相关的异常被放大。CCM 的生效区间是为了阻止这类错配；绕过区间等于绕过识别。</p><p>日频骨架一旦错，TAQ、IBES、指数成分都会沿错误主键传播。所以本课在数据单元的第一课：身份先于频率。</p>',9)),(t(),r(p,null,{default:e(()=>[n(E,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20CRSP%5B%22CRSP%20permno%20%E6%97%A5%E6%94%B6%E7%9B%8A%22%5D%20--%3E%20Link%5B%22CCM%20%E5%BD%93%E6%97%B6%E6%9C%89%E6%95%88%E9%93%BE%E6%8E%A5%22%5D%0A%20%20Link%20--%3E%20GV%5B%22gvkey%22%5D%0A%20%20GV%20--%3E%20CS%5B%22Compustat%20%E5%8F%AF%E7%9F%A5%E4%BC%9A%E8%AE%A1%22%5D%0A%20%20CRSP%20--%3E%20Delist%5B%22%E9%80%80%E5%B8%82%E6%94%B6%E7%9B%8A%E5%A4%84%E7%90%86%22%5D%0A%20%20Delist%20--%3E%20Panel%5B%22%E5%8F%AF%E5%9B%9E%E6%B5%8B%E9%9D%A2%E6%9D%BF%22%5D%0A%20%20CS%20--%3E%20Panel%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[s(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>CCM 覆盖并非宇宙中一切证券。私募、新近上市、非美会计主体会缺失。Compustat 工业与金融格式不同，银行用另一套科目。本课不提供未经许可批量转载 CRSP/Compustat 的数据。许可与引用以 WRDS 与供应商合同为准。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>用点-in-time 的 CCM 链接，禁止期末链接回填。</li><li>退市收益必须处理，否则小盘与困境因子被高估。</li><li>会计按可知日对齐，不按财季末日对齐。</li><li>出处：WRDS CCM；Shumway, <em>JF</em>, 1997。</li></ul>',4))])}const P=i(C,[["render",A]]);export{_ as __pageData,P as default};
